t`.`EVTotal` AS `EVTotal`,`hubitat_logging`.`IotaWatt`.`RangeTotal` AS `RangeTotal`,`hubitat_logging`.`IotaWatt`.`AllOther` AS `AllOther`,`hubitat_logging`.`IotaWatt`.`Voltage` AS `Voltage`,`hubitat_logging`.`IotaWatt`.`Frequency` AS `Frequency`,`hubitat_logging`.`IotaWatt`.`UpstairsBeds` AS `UpstairsBeds`,`hubitat_logging`.`IotaWatt`.`Office` AS `Office`,`hubitat_logging`.`IotaWatt`.`UtilityCloset` AS `UtilityCloset`,`hubitat_logging`.`IotaWatt`.`ClaireMini` AS `ClaireMini` from `hubitat_logging`.`IotaWatt` where `hubitat_logging`.`IotaWatt`.`Time` >= cast(date_format((select max(`r`.`Time`) from `hubitat_logging`.`IotaWatt` `r`) - interval (select `hubitat_logging`.`IotaWattRetentionState`.`RawRetentionDays` from `hubitat_logging`.`IotaWattRetentionState` where `hubitat_logging`.`IotaWattRetentionState`.`Id` = 1) day,'%Y-%m-%d %H:00:00') as datetime);

