aWattHoursbyMinute`.`FurnaceHours` AS `FurnaceHours`,`hubitat_logging`.`IotaWattHoursbyMinute`.`FridgeHours` AS `FridgeHours`,`hubitat_logging`.`IotaWattHoursbyMinute`.`KitchenHours` AS `KitchenHours`,`hubitat_logging`.`IotaWattHoursbyMinute`.`AllOtherHours` AS `AllOtherHours`,`hubitat_logging`.`IotaWattHoursbyMinute`.`UpstairsBedsHours` AS `UpstairsBedsHours`,`hubitat_logging`.`IotaWattHoursbyMinute`.`OfficeHours` AS `OfficeHours`,`hubitat_logging`.`IotaWattHoursbyMinute`.`UtilityClosetHours` AS `UtilityClosetHours`,`hubitat_logging`.`IotaWattHoursbyMinute`.`ClaireMiniHours` AS `ClaireMiniHours` from `hubitat_logging`.`IotaWattHoursbyMinute` where `hubitat_logging`.`IotaWattHoursbyMinute`.`DateDTS` >= cast(date_format((select max(`m`.`DateDTS`) from `hubitat_logging`.`IotaWattHoursbyMinute` `m`) - interval (select `hubitat_logging`.`IotaWattRetentionState`.`MinuteRetentionDays` from `hubitat_logging`.`IotaWattRetentionState` where `hubitat_logging`.`IotaWattRetentionState`.`Id` = 1) day,'%Y-%m-%d %H:00:00') as datetime);

CREATE OR REPLACE VIEW v_vue_power_minute AS SELECT BucketStartUTC AS `Time`, CASE WHEN COUNT(CASE WHEN Channel IN (17,18) THEN 1 END)=2 THEN SUM(CASE WHEN Channel IN (17,18) THEN Value ELSE 0 END) END AS `Total`,
MAX(CASE WHEN Channel=8 THEN Value END) AS `WaterHeater`,
MAX(CASE WHEN Channel=7 THEN Value END) AS `Furnace`,
MAX(CASE WHEN Channel=1 THEN Value END) AS `Fridge`,
MAX(CASE WHEN Channel=10 THEN Value END) AS `Kitchen`,
MAX(CASE WHEN Channel=3 THEN Value END) AS `ACTotal`,
MAX(CASE WHEN Channel=2 THEN Value END) AS `DryerTotal`,
MAX(CASE WHEN Channel=11 THEN Value END) AS `EVTotal`,
MAX(CASE WHEN Channel=4 THEN Value END) AS `RangeTotal`,
CASE WHEN COUNT(CASE WHEN Channel BETWEEN 1 AND 18 THEN 1 END)=18 THEN SUM(CASE WHEN Channel IN (17,18) THEN Value WHEN Channel BETWEEN 1 AND 16 THEN -Value ELSE 0 END) END AS `AllOther`,
MAX(CASE WHEN Channel=19 THEN Value END) AS `Voltage`,
MAX(CASE WHEN Channel=20 THEN Value END) AS `Frequency`,
NULL AS `UpstairsBeds`,
MAX(CASE WHEN Channel=13 THEN Value END) AS `Office`,
NULL AS `UtilityCloset`,
MAX(CASE WHEN Channel=12 THEN Value END) AS `ClaireMini`,
MAX(CASE WHEN Channel=5 THEN Value END) AS `Microwave`,
MAX(CASE WHEN Channel=6 THEN Value END) AS `WasherBidetLaundry`,
MAX(CASE WHEN Channel=9 THEN Value END) AS `Garage`,
MAX(CASE WHEN Channel=14 THEN Value END) AS `MasterBedroomCloset`,
MAX(CASE WHEN Channel=15 THEN Value END) AS `BasementBathroom`,
MAX(CASE WHEN Channel=16 THEN Value END) AS `LoftKidsBathWHF`,
MAX(CASE WHEN Channel=21 THEN Value END) AS `VoltageL2` FROM VuePowerMinute GROUP BY BucketStartUTC HAVING COUNT(CASE WHEN Channel<=18 THEN 1 END)>0;

CREATE OR REPLACE VIEW v_iotawatt_power_all AS SELECT `Time`, `Total`, `WaterHeater`, `Furnace`, `Fridge`, `Kitchen`, `ACTotal`, `DryerTotal`, `EVTotal`, `RangeTotal`, `AllOther`, `Voltage`, `Frequency`, `UpstairsBeds`, `Office`, `UtilityCloset`, `ClaireMini`, NULL AS `Microwave`, NULL AS `WasherBidetLaundry`, NULL AS `Garage`, NULL AS `MasterBedroomCloset`, NULL AS `BasementBathroom`, NULL AS `LoftKidsBathWHF`, NULL AS `VoltageL2` FROM v_iotawatt_power_all_legacy WHERE `Time` < COALESCE((SELECT CONVERT_TZ(MIN(BucketStartUTC),'UTC','America/Denver') FROM VuePowerMinute),'9999-12-31') UNION ALL SELECT CONVERT_TZ(`Time`,'UTC','America/Denver'), `Total`, `WaterHeater`, `Furnace`, `Fridge`, `Kitchen`, `ACTotal`, `DryerTotal`, `EVTotal`, `RangeTotal`, `AllOther`, `Voltage`, `Frequency`, `UpstairsBeds`, `Office`, `UtilityCloset`, `ClaireMini`, `Microwave`, `WasherBidetLaundry`, `Garage`, `MasterBedroomCloset`, `BasementBathroom`, `LoftKidsBathWHF`, `VoltageL2` FROM v_vue_power_minute;

CREATE OR REPLACE VIEW v_home_power_all AS SELECT CONVERT_TZ(`Time`,'America/Denver','UTC') AS `Time`, `Total`, `WaterHeater`, `Furnace`, `Fridge`, `Kitchen`, `ACTotal`, `DryerTotal`, `EVTotal`, `RangeTotal`, `AllOther`, `Voltage`, `Frequency`, `UpstairsBeds`, `Office`, `UtilityCloset`, `ClaireMini`, NULL AS `Microwave`, NULL AS `WasherBidetLaundry`, NULL AS `Garage`, NULL AS `MasterBedroomCloset`, NULL AS `BasementBathroom`, NULL AS `LoftKidsBathWHF`, NULL AS `VoltageL2` FROM v_iotawatt_power_all_legacy WHERE `Time` < COALESCE((SELECT CONVERT_TZ(MIN(BucketStartUTC),'UTC','America/Denver') FROM VuePowerMinute),'9999-12-31') UNION ALL SELECT `Time`, `Total`, `WaterHeater`, `Furnace`, `Fridge`, `Kitchen`, `ACTotal`, `DryerTotal`, `EVTotal`, `RangeTotal`, `AllOther`, `Voltage`, `Frequency`, `UpstairsBeds`, `Office`, `UtilityCloset`, `ClaireMini`, `Microwave`, `WasherBidetLaundry`, `Garage`, `MasterBedroomCloset`, `BasementBathroom`, `LoftKidsBathWHF`, `VoltageL2` FROM v_vue_power_minute;

CREATE OR REPLACE VIEW v_vue_energy_minute AS SELECT BucketStartUTC AS `DateDTS`, CASE WHEN COUNT(CASE WHEN Channel IN (17,18) THEN 1 END)=2 THEN SUM(CASE WHEN Channel IN (17,18) THEN WattHours ELSE 0 END) END AS `TotalWattHours`,
MAX(CASE WHEN Channel=3 THEN WattHours END) AS `ACHours`,
MAX(CASE WHEN Channel=2 THEN WattHours END) AS `DryerHours`,
MAX(CASE WHEN Channel=4 THEN WattHours END) AS `RangeHours`,
MAX(CASE WHEN Channel=8 THEN WattHours END) AS `WaterHeaterHours`,
MAX(CASE WHEN Channel=11 THEN WattHours END) AS `EVHours`,
MAX(CASE WHEN Channel=7 THEN WattHours END) AS `FurnaceHours`,
MAX(CASE WHEN Channel=1 THEN WattHours END) AS `FridgeHours`,
MAX(CASE WHEN Channel=10 THEN WattHours END) AS `KitchenHours`,
CASE WHEN COUNT(CASE WHEN Channel BETWEEN 1 AND 18 THEN 1 END)=18 THEN SUM(CASE WHEN Channel IN (17,18) THEN WattHours WHEN Channel BETWEEN 1 AND 16 THEN -WattHours ELSE 0 END) END AS `AllOtherHours`,
NULL AS `UpstairsBedsHours`,
MAX(CASE WHEN Channel=13 THEN WattHours END) AS `OfficeHours`,
NULL AS `UtilityClosetHours`,
MAX(CASE WHEN Channel=12 THEN WattHours END) AS `ClaireMiniHours`,
MAX(CASE WHEN Channel=5 THEN WattHours END) AS `MicrowaveHours`,
MAX(CASE WHEN Channel=6 THEN WattHours END) AS `WasherBidetLaundryHours`,
MAX(CASE WHEN Channel=9 THEN WattHours END) AS `GarageHours`,
MAX(CASE WHEN Channel=14 THEN WattHours END) AS `MasterBedroomClosetHours`,
MAX(CASE WHEN Channel=15 THEN WattHours END) AS `BasementBathroomHours`,
MAX(CASE WHEN Channel=16 THEN WattHours END) AS `LoftKidsBathWHFHours` FROM VuePowerMinute WHERE Channel<=18 GROUP BY BucketStartUTC HAVING COUNT(CASE WHEN Channel<=18 THEN 1 END)>0;

CREATE OR REPLACE VIEW v_iotawatt_energy_all AS SELECT `DateDTS`, `TotalWattHours`, `ACHours`, `DryerHours`, `RangeHours`, `WaterHeaterHours`, `EVHours`, `FurnaceHours`, `FridgeHours`, `KitchenHours`, `AllOtherHours`, `UpstairsBedsHours`, `OfficeHours`, `UtilityClosetHours`, `ClaireMiniHours`, NULL AS `MicrowaveHours`, NULL AS `WasherBidetLaundryHours`, NULL AS `GarageHours`, NULL AS `MasterBedroomClosetHours`, NULL AS `BasementBathroomHours`, NULL AS `LoftKidsBathWHFHours` FROM v_iotawatt_energy_all_legacy WHERE `DateDTS` < COALESCE((SELECT CONVERT_TZ(MIN(BucketStartUTC),'UTC','America/Denver') FROM VuePowerMinute),'9999-12-31') UNION ALL SELECT CONVERT_TZ(`DateDTS`,'UTC','America/Denver'), `TotalWattHours`, `ACHours`, `DryerHours`, `RangeHours`, `WaterHeaterHours`, `EVHours`, `FurnaceHours`, `FridgeHours`, `KitchenHours`, `AllOtherHours`, `UpstairsBedsHours`, `OfficeHours`, `UtilityClosetHours`, `ClaireMiniHours`, `MicrowaveHours`, `WasherBidetLaundryHours`, `GarageHours`, `MasterBedroomClosetHours`, `BasementBathroomHours`, `LoftKidsBathWHFHours` FROM v_vue_energy_minute;

CREATE OR REPLACE VIEW v_home_energy_all AS SELECT CONVERT_TZ(`DateDTS`,'America/Denver','UTC') AS `DateDTS`, `TotalWattHours`, `ACHours`, `DryerHours`, `RangeHours`, `WaterHeaterHours`, `EVHours`, `FurnaceHours`, `FridgeHours`, `KitchenHours`, `AllOtherHours`, `UpstairsBedsHours`, `OfficeHours`, `UtilityClosetHours`, `ClaireMiniHours`, NULL AS `MicrowaveHours`, NULL AS `WasherBidetLaundryHours`, NULL AS `GarageHours`, NULL AS `MasterBedroomClosetHours`, NULL AS `BasementBathroomHours`, NULL AS `LoftKidsBathWHFHours` FROM v_iotawatt_energy_all_legacy WHERE `DateDTS` < COALESCE((SELECT CONVERT_TZ(MIN(BucketStartUTC),'UTC','America/Denver') FROM VuePowerMinute),'9999-12-31') UNION ALL SELECT `DateDTS`, `TotalWattHours`, `ACHours`, `DryerHours`, `RangeHours`, `WaterHeaterHours`, `EVHours`, `FurnaceHours`, `FridgeHours`, `KitchenHours`, `AllOtherHours`, `UpstairsBedsHours`, `OfficeHours`, `UtilityClosetHours`, `ClaireMiniHours`, `MicrowaveHours`, `WasherBidetLaundryHours`, `GarageHours`, `MasterBedroomClosetHours`, `BasementBathroomHours`, `LoftKidsBathWHFHours` FROM v_vue_energy_minute;

CREATE OR REPLACE VIEW v_home_solar_power_all AS SELECT CONVERT_TZ(`Time`,'America/Denver','UTC') AS `Time`, `TotalGrid`, `TotalSolar`, `TotalHeatPump` FROM v_iotawatt_solar_power_all;

CREATE OR REPLACE VIEW v_home_solar_energy_all AS SELECT CONVERT_TZ(`DateDTS`,'America/Denver','UTC') AS `DateDTS`, `TotalGridHours`, `TotalSolarHours`, `TotalHeatPumpHours` FROM v_iotawatt_solar_energy_all;

CREATE OR REPLACE VIEW v_home_solar_accounting_all AS SELECT CONVERT_TZ(`DateDTS`,'America/Denver','UTC') AS `DateDTS`, `SolarWh`, `ConsumedWh`, `SelfConsumedWh`, `Cost` FROM v_iotawatt_solar_accounting_all;

CREATE OR REPLACE VIEW v_home_solar_cost_trend_all AS SELECT CONVERT_TZ(`DateDTS`,'America/Denver','UTC') AS `DateDTS`, `SolarCost` FROM v_solar_cost_trend_all;
